rules=[('HG1','Owner','Proposed HOST application-owned IoHealth accompanies existing document/session binding. It is permission/safety metadata only, not replacement document content/history/baselines. No new domain setter, global singleton or IO journal reader/writer.'),('HG2','States','IoHealth = Healthy | WriteInFlight{request_id,capture_key} | RecoveryBlocked{reason,evidence_key}. reason = IoRecoveryRequired | CommitEvidenceMismatch. Evidence keeps exact original diagnostics/receipt; not inferred from UI labels.'),('HG3','Reservation','Under existing owner mutex, authenticate caller + document/session/generation + expected revision, then atomically Healthy -> WriteInFlight and capture immutable data. Release mutex for codec/IO. Any racing destructive operation observes not-Healthy and rejects before domain prepare/commit or IO.'),('HG4','Terminal','Verified ordinary completion -> Healthy only if matching reservation. IO RecoveryRequired or SP receipt mismatch -> RecoveryBlocked even if owner detached. Retain safety evidence before publishing response. A stale completion cannot clear another reservation or blocked state.'),('HG5','No automatic recovery','No clear/reset/retry button, timeout lease theft, synthetic ACK or reconstruct-new-DocumentSession workaround. Current public S1 has no recovery setter and current IO Port has no explicit recovery-attestation API; unblock/recovery transaction needs separate exact approved seam. This proposal intentionally has no RecoveryBlocked -> Healthy transition.'),('HG6','Read-only operations','Allow projection/evidence inspection and copy diagnostics as inert text while blocked. Capture for inspection must not trigger autosave or material writes. Deny editing/undo/merge/formal save/recovery snapshot/material apply/replace active content; no implicit backup-as-recovery bypass.'),('HG7','Detach','Close/window/session change revokes caller mutation authority but does not erase blocked target evidence. Keep records in owning HOST application lifecycle until explicit approved recovery flow. Reopening same canonical target in runtime must inherit block, not start Healthy merely due a fresh UUID/session.'),('HG8','Target scope','Block by trusted canonical target binding identity, not untrusted UI spelling. Aliases must resolve through approved native binding seam; if alias identity is unverified refuse mutation rather than instantiate another Healthy owner. Exact cross-session target-key ownership and startup policy must be integrated with final caller/native package before implementation.'),('HG9','Persistence limit','This is a runtime safety proposal only. It does not claim durable quarantine across restart; restarting is not evidence of recovery. IO-private journal remains owned by adapter. Startup/unblock proof is an explicit unresolved architecture gate, not silently implemented by HOST filesystem scans.'),('HG10','Projection','effective_can_mutate = authenticated_current_owner && S1 editable && IoHealth Healthy. Project both domain status and io_health separately; never forge S1 SessionStatus::RecoveryRequired. Error RecoveryBlocked includes inert evidence reference; Busy includes owned request reference only for authorized caller.')]
operations=[('edit/prepare+commit','deny before prepare/commit','deny before prepare/commit'),('undo','deny before S1 undo','deny before S1 undo'),('formal save','Busy before encode/IO','RecoveryBlocked before encode/IO'),('recovery snapshot save','Busy before capture-for-write/IO','RecoveryBlocked before capture-for-write/IO'),('merge/import apply','deny before authoritative mutation','deny before authoritative mutation'),('material mutation','deny within same document boundary','deny within same document boundary'),('content replace/reload install','deny replacing current session','deny replacement workaround'),('projection/diagnostic query','allow read-only','allow read-only'),('close/detach','revoke presentation, retain reservation','revoke presentation, retain blocked target record')]
tests=[{'id':f'M04-HG-{i+1:02d}','given':'valid caller; IoHealth WriteInFlight versus RecoveryBlocked','when':a,'then':{'WriteInFlight':b,'RecoveryBlocked':c},'oracle':'domain revision/content/history/formal+snapshot baselines and filesystem byte snapshots unchanged for denied operations; no dependency calls beyond authorization','status':'PLANNED_NOT_RUN'} for i,(a,b,c) in enumerate(operations)]
tests += [{'id':'M04-HG-10','given':'two concurrent Healthy save requests, barrier at reserve','when':'both reserve','then':'exactly one in-flight owner; other Busy; one IO call','status':'PLANNED_NOT_RUN'},{'id':'M04-HG-11','given':'request A detached, later request B/blocked evidence owns target','when':'late A completion arrives','then':'no clear/reset of B/blocked record; no ACK to replacement session','status':'PLANNED_NOT_RUN'},{'id':'M04-HG-12','given':'blocked target, new session UUID','when':'same canonical target reopens','then':'inherits blocked state; no new Healthy session bypass','status':'PLANNED_NOT_RUN'},{'id':'M04-HG-13','given':'S1 editable but io health blocked','when':'effective projection requested','then':'can_mutate=false; actual S1 status unchanged','status':'PLANNED_NOT_RUN'}]
spec={'module':'M04','slice':'S2 HOST IO health safety-gate proposal','status':'PROPOSED_WITH_EXPLICIT_STARTUP_RECOVERY_ARCHITECTURE_GATE','at':now,'addresses':'readiness R4 recommendation A, not approved and not full S2 envelope','rules':[{'id':a,'topic':b,'contract':c} for a,b,c in rules],'matrix':[{'operation':a,'WriteInFlight':b,'RecoveryBlocked':c} for a,b,c in operations],'tests':tests,'architecture':{'hexagonal':'UI/input commands -> HOST authority+IO health guard -> existing S1/codec/IO ports','dependency':'HOST reads S1 status and guards invocation; S1 has no new infrastructure dependency; IO continues owning its journal','ownership':'authoritative document remains S1; application request/safety records are derived and target-bound','transaction':'atomic reserve -> unlocked codec/IO -> matching terminal transition -> independently authorized ACK; gate does not invent file rollback'},'decisions':[{'id':'M04-HG-D1','proposal':'HOST application gate without S1 API/lifecycle mutation'},{'id':'M04-HG-D2','proposal':'matrix and no automatic unblock; preserve evidence on detach'},{'id':'M04-HG-D3','proposal':'Require exact target-key/startup recovery proof before implementation; do not claim runtime-only safety is restart-safe'}],'unresolved_gate':{'status':'ARCHITECTURE_GAP_FOR_COMPLETE_RECOVERY_LIFECYCLE','required':'Attested clear/startup/reopen policy for blocked/uncertain targets with alias-safe target identity','available':'existing FileCommitPort acquire_write/read/replace_checked and adapter-private journal; S1 has no enter/clear recovery API','missing':'approved proof-bearing recovery/unblock input/output contract and exact caller target identity migration','options':['Extend IO with separately approved recovery-attestation seam and corresponding native failure tests','Keep affected target read-only across the defined recovery lifecycle until explicit external verified reopen workflow is approved; exact persistence/proof still needs design'],'restriction':'Do not choose/implement either option automatically; this proposal is not READY_FOR_IMPLEMENTATION.'},'remaining':'Integrate R2 codec, SP proof/ACK, HG startup/target identity and actual caller migration in one precise S2 package. No changes to previously accepted S1/IO.','verification':{'source_unchanged':796,'product_tests':'NOT RUN','build':'NOT RUN','RED':'NOT RUN','native':'NOT RUN'},'next':'Complete exact startup/clear proof option and target identity ownership within planning, then consolidate Owner choices. Continue other unblocked work; no new Port or Skeleton until approved.'}
